    factory = WebSocketClientFactory()
    factory.protocol = CustomWebSocketClient

    loop = asyncio.get_event_loop()
    await loop.create_connection(factory, 'ws://159.122.237.12/ws', 80)

if __name__ == '__main__':
    event_loop = asyncio.get_event_loop()
    event_loop.run_until_complete(start_client())
    event_loop.run_forever()
