from .types import IsaacusSageMakerRuntimeEndpoint


class _CyclicIterator:
    def __init__(self, elements: Iterable[Any]) -> None:
        self._elements = list(elements)
        self._iterator = cycle(self._elements) if self._elements else None

    def get_next(self) -> Optional[Any]:
        if self._iterator is None:
            return None

        return next(self._iterator)


class EndpointRouter:
    def __init__(self, endpoints: Sequence[IsaacusSageMakerRuntimeEndpoint]) -> None:
        if not endpoints:
            raise ValueError("At least one endpoint must be provided.")
        if not all(isinstance(e, IsaacusSageMakerRuntimeEndpoint) for e in endpoints):
            raise TypeError("All provided endpoints must be of the type `IsaacusSageMakerRuntimeEndpoint`.")
        if not all(e.name for e in endpoints):
            raise ValueError("All provided endpoints must have a non-empty name.")

        self._lock = Lock()
        self._generic_cycle = _CyclicIterator([e for e in endpoints if e.models is None])

        model_to_endpoints: Dict[str, List[IsaacusSageMakerRuntimeEndpoint]] = defaultdict(list)

        for endpoint in endpoints:
            if endpoint.models is not None:
                for model_name in endpoint.models:
                    model_to_endpoints[model_name].append(endpoint)

        for endpoint in endpoints:
            if endpoint.models is None:
                for model_name in model_to_endpoints.keys():
                    model_to_endpoints[model_name].append(endpoint)

        self._model_specific_cycles: Dict[str, _CyclicIterator] = {
            model: _CyclicIterator(endpoints) for model, endpoints in model_to_endpoints.items()
        }

    def select_endpoint(self, model: Optional[str]) -> Optional[IsaacusSageMakerRuntimeEndpoint]:
        with self._lock:
            if model and model in self._model_specific_cycles:
                selected = self._model_specific_cycles[model].get_next()

                if selected is not None:
                    return selected

            return self._generic_cycle.get_next()

