_UNPROXIABLE_HEADERS = {
    "host",
    "content-length",
    "connection",
    "keep-alive",
    "proxy-authenticate",
    "proxy-authorization",
    "te",
    "trailers",
    "transfer-encoding",
    "upgrade",
    "authorization",
}


def _parse_message_body(message: Union[httpx.Request, httpx.Response]) -> Any:
    content_type = message.headers.get("content-type", "")

    if "application/json" in content_type:
        return orjson.loads(message.content)

    if message.content:
        raise ValueError("Only message bodies with the content type `application/json` are supported.")

    return message.content


def _extract_model_name(body: Any) -> Optional[str]:
    if isinstance(body, dict) and "model" in body:
        return body["model"]

    return None


def _filter_headers(headers: Mapping[str, str]) -> Dict[str, str]:
    return {k: v for k, v in headers.items() if k.lower() not in _UNPROXIABLE_HEADERS}


def _create_request_payload(
    request: httpx.Request,
    body: Any,
) -> bytes:
    invocation = SageMakerRequest(
        path=request.url.path,
        method=request.method,
        headers=_filter_headers(request.headers),
        data=body,
    )
    return msgspec.json.encode(invocation)


def _handle_response(response: httpx.Response) -> httpx.Response:
    if response.status_code < 400:
        return response

    content_type = response.headers.get("content-type", "")
    payload: Optional[Dict] = None

    if "application/json" in content_type:
        payload = orjson.loads(response.content)

    if not isinstance(payload, dict):
        return response

    original_status = payload.get("OriginalStatusCode")
    if not original_status:
        return response

    original_message = payload.get("OriginalMessage")
    if not original_message:
        return response

    try:
        original_message = orjson.loads(original_message)
    except Exception:
        return response

    headers = response.headers.copy()
    headers["content-type"] = "application/json"

    return httpx.Response(
        status_code=int(original_status),
        headers=headers,
        json=original_message,
        request=response.request,
    )


def _fetch_credentials(
    endpoint: SageMakerEndpoint,
    credentials_cache: Dict[Optional[str], botocore.credentials.Credentials],
    default_profile: Optional[str] = None,
    session_kwargs: Optional[Dict[str, Any]] = None,
) -> botocore.credentials.Credentials:
    profile = endpoint.profile or default_profile

    if profile not in credentials_cache:
        session_kwargs = dict(session_kwargs or {})

        if profile is not None:
            session_kwargs["profile_name"] = profile

        session = boto3.Session(**session_kwargs)
        endpoint_credentials = session.get_credentials()

        if endpoint_credentials is None:
            raise RuntimeError(f"Could not retrieve AWS credentials for profile '{profile}'.")

        credentials_cache[profile] = endpoint_credentials

    return credentials_cache[profile]


def _prepare_request(
    self: SageMakerHTTPClient | AsyncSageMakerHTTPClient,
    request: httpx.Request,
) -> httpx.Request:
    request_body = _parse_message_body(request)
    model_name = _extract_model_name(request_body)
    endpoint = self._router.select(model_name)

    if endpoint is None:
        raise RuntimeError(f"No SageMaker endpoints registered for model '{model_name}'.")

