def convert_camel_to_kebab(data):
    if isinstance(data, dict):
        new_data = {}
        for k, v in data.items():
            kebab_key = re.sub(r'([a-z0-9])([A-Z])', r'\1-\2', k).lower()
            new_data[kebab_key] = convert_camel_to_kebab(v) if isinstance(v, dict) else v
        return new_data
    elif isinstance(data, list):
        return [convert_camel_to_kebab(item) for item in data]
    else:
        return data


def check_ipv6(host):
    try:
        ipaddress.IPv6Address(host)
        return True
    except ipaddress.AddressValueError:
        return False


def transform_vmess_link(link):
    decoded_data = json.loads(base64.b64decode(link[8:]).decode('utf-8'))

    decoded_data['type'] = decoded_data['net']
    decoded_data['path'] = decoded_data.get('path', None)
    decoded_data['aid'] = decoded_data.get('aid', None)
    decoded_data['security'] = decoded_data.get('tls', None)

    if check_ipv6(decoded_data["add"]):
        decoded_data["add"] = "[{}]".format(decoded_data["add"])

    UrlComponents = namedtuple(
        'UrlComponents',
        ['scheme', 'netloc', 'url', 'path', 'query', 'fragment']
    )

    transformed_url = urlunparse(
        UrlComponents(
            scheme='vmess',
            netloc='{user}@{host}:{port}'.format(user=decoded_data['id'], host=decoded_data["add"], port=decoded_data["port"]),
            query=urlencode(decoded_data),
            path='',
            url='',
            fragment=decoded_data['ps']
        )
    )
